    open_count = brackets.count('<')
    close_count = brackets.count('>')

    # Check if the number of opening brackets is equal to the number of closing brackets
    if open_count != close_count:
        return False

    # Iterate through the input string and check if the brackets appear in the correct sequence
    stack = []
    for char in brackets:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if not stack or stack[-1] != '<':
                return False
            stack.pop()

    # Return True if all conditions are met, otherwise return False
    return len(stack) == 0
